const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',course:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',ranking:'<path d="M8 3h8v5a4 4 0 0 1-8 0zM8 5H4v2a4 4 0 0 0 4 4m8-6h4v2a4 4 0 0 1-4 4M12 12v6m-4 3h8m-8-3h8"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>'};
function navIcon(id){return '<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round">'+icons[id]+'</svg>'}
home=function(){const u=user(),list=db.courses.slice().sort((a,b)=>Number(!!a.demo)-Number(!!b.demo));const featured=list.find(c=>!c.demo)||list[0];const progress=u.courseProgress?.[featured.id]||{read:[],attempts:[]};$('#content').innerHTML=`<div class="dashboard-intro"><div class="eyebrow">АКАДЕМИЯ КОМАНДЫ</div><h1>Привет, ${esc(u.name.split(' ')[0])}!</h1><p>Твой следующий шаг к уверенной смене.</p></div><section class="welcome-banner"><span class="eyebrow">В ОДНОМ РИТМЕ</span><span class="sticker" aria-hidden="true">✦</span><h2>Вливайся.<br>Учись. Зажигай!</h2><p>${progress.read.length?'Продолжим с того места, где остановились?':'Знакомься с командой, изучай стандарты и готовься к ярким сменам.'}</p><button class="btn" id="featured-course">${progress.read.length?'Продолжить курс':'Начать знакомство'} →</button></section><div class="course-section-title"><h2>Мои курсы</h2><span class="muted">${list.length} курсов</span></div><div class="course-list">${list.map(c=>{const p=u.courseProgress?.[c.id]||{read:[],attempts:[]},pct=Math.round(p.read.length/Math.max(1,c.lessons.length)*100);return `<article class="card learning-card ${c.demo?'demo':''}"><div class="learning-cover">${!c.demo&&c.lessons[0]?.images?.[0]?`<img src="${esc(c.lessons[0].images[0])}" alt="" loading="lazy">`:''}<span class="tag">${c.demo?'90-е + Руки Вверх Бар':c.kind==='internship'?'90-е · Стажировка':c.id==='welcome-90'?'90-е · Welcome':'90-е · Сервис'}</span><br><span class="cover-label">${c.coverLabel||(c.demo?'Сервис<br>на отлично':c.id==='waiter-standards'?'Стандарты<br>сервиса':'Свои<br>в команде')}</span></div><div class="learning-body"><h3>${esc(c.id==='welcome-90'?'Знакомство с «90-е»':c.title)}</h3><p>${esc(c.demo?'Короткие уроки об общении с гостями и уверенном сервисе.':c.id==='waiter-standards'?'Правила работы, открытие смены, обслуживание и чек-бэк.':c.id==='welcome-90'?'Наша атмосфера, гости, команда и твой первый день.':c.description)}</p><div class="course-meta"><span>${c.lessons.length} уроков</span><span>·</span><span>${c.assessments?.length?c.assessments.length+' '+((c.assessments.length%100<11||c.assessments.length%100>14)&&c.assessments.length%10===1?'проверка':(c.assessments.length%100<11||c.assessments.length%100>14)&&c.assessments.length%10>=2&&c.assessments.length%10<=4?'проверки':'проверок'):c.questions.length?'Есть тест':'Материалы курса'}</span></div><div class="progress"><i style="width:${pct}%"></i></div><div class="row"><span class="muted">Изучено ${p.read.length} из ${c.lessons.length}</span><strong style="font-size:12px">${pct}%</strong></div><button class="btn ${c.demo?'secondary':''}" data-course-card="${esc(c.id)}">${p.read.length?'Продолжить':'Открыть курс'} →</button></div></article>`}).join('')}</div>`;const open=id=>{view='course';selectCourse(id);window.scrollTo(0,0)};$('#featured-course').onclick=()=>open(featured.id);document.querySelectorAll('[data-course-card]').forEach(b=>b.onclick=()=>open(b.dataset.courseCard))};
let enhancing=false,mobileFiltersOpen=false;
function enhanceMobile(){if(enhancing)return;enhancing=true;try{
 document.querySelectorAll('.brand,.mobilebrand').forEach(el=>{el.setAttribute('role','img');el.setAttribute('aria-label','90-е и Руки Вверх Бар · Академия команды')});
 if(manager)document.querySelectorAll('#managerbody h2').forEach(h=>{const suffix=' · '+activeCourse().title;if(h.textContent.endsWith(suffix))h.textContent=h.textContent.slice(0,-suffix.length)});
 document.querySelectorAll('.bottomnav button,.nav button').forEach(b=>{if(b.dataset.polished)return;b.dataset.polished='1';const txt=b.textContent;const id=txt.includes('Рейтинг')?'ranking':txt.includes('Профиль')||txt.includes('профиль')?'profile':txt.includes('Курс')||txt.includes('курса')?'course':'home';const label={home:'Обучение',course:'Программа',ranking:'Рейтинг',profile:'Профиль'}[id];b.innerHTML=navIcon(id)+'<span>'+label+'</span>';b.classList.toggle('active',!manager&&(id===view||(id==='home'&&view==='home')||(id==='course'&&['lesson','quiz'].includes(view))));b.setAttribute('aria-label',label);if(b.classList.contains('active'))b.setAttribute('aria-current','page')});
 const sw=$('#switch');if(sw&&!sw.dataset.polished){sw.dataset.polished='1';sw.textContent=manager?'← Моё обучение':'Кабинет менеджера';}
 document.querySelectorAll('.bottomnav').forEach(nav=>{if(nav.dataset.ordered)return;nav.dataset.ordered='1';const buttons=[...nav.querySelectorAll('button')];const rating=buttons.find(b=>b.textContent.includes('Рейтинг')),profile=buttons.find(b=>b.textContent.includes('Профиль'));if(rating&&profile)nav.insertBefore(rating,profile)});
 document.querySelectorAll('#active-course option,#ranking-course option').forEach(o=>{if(o.value==='welcome-90'&&o.textContent!=='Знакомство с «90-е»')o.textContent='Знакомство с «90-е»';});
 const register=document.querySelector('.register');if(register&&!register.dataset.polished){register.dataset.polished='1';register.querySelector('h1').innerHTML='Свои<br>в команде.';register.querySelector('h1+p').textContent='Выбери своё заведение и должность — и начнём знакомство.';const h=register.querySelector('h2');h.textContent='Давай познакомимся';}
 document.querySelectorAll('.tablewrap table').forEach(table=>{const labels=[...table.querySelectorAll('th')].map(x=>x.textContent);table.querySelectorAll('tr').forEach(tr=>tr.querySelectorAll('td').forEach((td,i)=>td.dataset.label=labels[i]||''))});
 document.querySelectorAll('.rankfilters').forEach(filters=>{if(filters.parentElement.classList.contains('filterbox'))return;const details=document.createElement('details');details.className='filterbox';details.open=window.innerWidth>800||mobileFiltersOpen;details.ontoggle=()=>{if(details.isConnected)mobileFiltersOpen=details.open};const summary=document.createElement('summary');summary.textContent='Фильтры и сортировка';filters.before(details);details.append(summary,filters)});
 if($('#rank-results')){const card=$('#rank-results').closest('.card'),explain=card.querySelector(':scope>p.muted');if(explain&&!explain.closest('details')){const d=document.createElement('details');d.className='source-details';const summary=document.createElement('summary');summary.textContent='Как считается рейтинг';explain.before(d);d.append(summary,explain)}const head=card.querySelector('h2');if(head&&head.textContent==='Рейтинг обучения')head.textContent='Команда';const reset=$('#rank-reset'),box=card.querySelector('.filterbox');if(reset&&box&&!reset.closest('details'))box.append(reset);const n=Object.entries(rankFilters).filter(([k,v])=>v&&k!=='search'&&!(k==='sort'&&v==='best')&&!(k==='period'&&v==='all')).length,summary=box?.querySelector('summary'),label=n?'Фильтры и сортировка · '+n:'Фильтры и сортировка';if(summary&&summary.textContent!==label)summary.textContent=label;}
 document.querySelectorAll('#content>p>a, .reading article>a').forEach(a=>{if(!a.textContent.includes('Оригинал')||a.closest('details'))return;const p=a.parentElement;const details=document.createElement('details');details.className='source-details';const summary=document.createElement('summary');summary.textContent='Источник материала';const content=document.createElement('div');details.append(summary,content);if(p.tagName==='P'){p.replaceWith(details);content.append(a)}else{a.before(details);content.append(a)}});
 const picker=$('#active-course');if(picker&&((view==='home'&&!manager)||view==='quiz')){picker.parentElement.style.display='none'}
 if(view==='quiz'){document.querySelectorAll('.bottomnav button,.nav button,#switch').forEach(b=>b.disabled=true)}
 if(view==='course'&&!manager){const h=$('#content h1');if(h){h.classList.add('course-head-title');if(activeCourse().id==='welcome-90'&&h.textContent!=='Знакомство с «90-е»')h.textContent='Знакомство с «90-е»';}}
 document.querySelectorAll('.note').forEach(n=>{if(n.textContent.includes('Демокоманда:')||n.textContent.includes('Менеджерская роль демонстрационная')||n.textContent.includes('Переключение ролей открыто')){if(n.closest('details'))return;const d=document.createElement('details');d.className='source-details';const summary=document.createElement('summary');summary.textContent='О демонстрационном режиме';n.before(d);d.append(summary,n)}});
 document.querySelectorAll('#content>.field label').forEach(l=>{if(l.htmlFor==='active-course'&&l.textContent!=='Выбранный курс')l.textContent='Выбранный курс';});
}finally{enhancing=false}}
const mobileRender=render;render=function(){mobileRender();enhanceMobile()};
const mobileTest=test;test=function(){mobileTest();window.scrollTo(0,0)};
let polishQueued=false;new MutationObserver(()=>{if(!polishQueued){polishQueued=true;requestAnimationFrame(()=>{polishQueued=false;enhanceMobile()})}}).observe(document.getElementById('app'),{childList:true,subtree:true});
render();
